# Write to translations.py
with open('core/translations.py', 'r', encoding='utf-8') as f:
    content = f.read()

idx = content.rfind('}\n\n# Language display names')
if idx == -1:
    idx = content.rfind('}\n\n#')
if idx == -1:
    idx = content.rfind('}\n')

lines = []
for key, vals in phase4_keys.items():
    entry = f"    '{key}': {{"
    for lang_code, lang_val in vals.items():
        if isinstance(lang_val, set):
            lang_val = list(lang_val)[0]
        escaped = lang_val.replace("'", "\\'")
        entry += f"'{lang_code}': '{escaped}', "
    entry += "},"
    lines.append(entry)

new_block = "\n\n    # ===================== PHASE 4 — PRODUCT MANAGEMENT =====================\n" + "\n".join(lines) + "\n"
content = content[:idx] + new_block + content[idx:]

with open('core/translations.py', 'w', encoding='utf-8') as f:
    f.write(content)

print(f"Added {len(phase4_keys)} Phase 4 translation keys")
